(()=>{'use strict';const U='https://gfggmkeucgqkkyvummpu.supabase.co',K='sb_publishable_ptCVbq9h15prKhT0OO5Zmg_LkE3cbK0';const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));async function api(path){const r=await fetch(U+path,{headers:{apikey:K,Authorization:`Bearer ${K}`,Accept:'application/json'}});if(!r.ok)throw Error();return r.json()}const icon=c=>c==='Infrastruktur'?'🛣️':c==='Kesehatan'?'🏥':c==='Pendidikan'?'🏫':c==='Lingkungan'?'🌱':c==='Ekonomi'?'📈':c==='Sosial'?'👥':c==='Kemiskinan'?'🏠':c==='Transportasi'?'🚌':c==='Pertanian'?'🌾':c==='Bencana'?'🌧️':c==='Air Bersih'?'💧':'◉';function home(){const host=document.getElementById('home');if(!host)return;host.innerHTML=`<div class="clean-home"><section class="clean-hero"><div class="clean-hero-copy"><span class="clean-eyebrow">WASKITA · PORTAL DATA & ASPIRASI PUBLIK</span><h1>Indonesia dalam satu<br><strong>peta masalah.</strong></h1><p>Telusuri wilayah, buka masalah yang tercatat, lihat data publik, dan sampaikan laporan warga.</p><form class="clean-search" id="cleanSearch"><span>⌕</span><input id="cleanQuestion" placeholder="Cari masalah, provinsi, kabupaten, kecamatan, atau desa…"><button type="submit">Cari</button></form><div class="hero-actions"><button data-view="map" class="clean-primary">Jelajahi Peta Indonesia →</button><button data-view="report" class="clean-ghost">Suara Warga</button></div></div><div class="clean-garuda" role="img" aria-label="Garuda IKN"></div></section><section class="clean-stats" id="liveStats"><article><b>—</b><strong>Provinsi</strong><span>data wilayah publik</span></article><article><b>—</b><strong>Kabupaten/Kota</strong><span>data wilayah publik</span></article><article><b>—</b><strong>Kecamatan</strong><span>data wilayah publik</span></article><article><b>—</b><strong>Masalah publik</strong><span>tercatat di sistem</span></article></section><section class="clean-feature"><article class="clean-panel clean-map-card"><div class="clean-panel-head"><div><span>PETA INTERAKTIF</span><h2>Telusuri Indonesia</h2><p>Klik provinsi untuk masuk ke tingkat wilayah berikutnya.</p></div><button data-view="map" class="clean-link">Buka peta →</button></div><div class="clean-map-placeholder"><div id="homeIndonesiaMap" class="clean-map-real"></div><div class="clean-map-caption">Peta provinsi · klik wilayah untuk membuka detail</div></div></article><article class="clean-panel clean-report-card"><span>SUARA WARGA</span><h2>Laporkan masalah di sekitar Anda</h2><p>Masukkan informasi publik tentang masalah di wilayah Anda. Laporan warga dibedakan dari data yang sudah terverifikasi.</p><button data-view="report" class="clean-primary">Buat Laporan Warga →</button><div class="report-steps"><span>01 Kirim</span><span>02 Verifikasi</span><span>03 Tampil publik</span></div></article></section><section class="clean-section"><div class="clean-section-head"><div><span>MASALAH TERBARU</span><h2>Masalah yang tercatat</h2><p>Data berasal dari sistem publik WASKITA.</p></div><button data-view="problems" class="clean-link">Lihat semua masalah →</button></div><div class="clean-issues" id="homeIssues"><div class="clean-loading">Memuat data masalah…</div></div></section><section class="clean-feature clean-lower"><article class="clean-panel"><div class="clean-panel-head"><div><span>DATA & STATISTIK</span><h2>Masalah berdasarkan bidang</h2><p>Setiap kategori memiliki ikon dan jumlah berdasarkan data yang tersedia.</p></div><button data-view="data" class="clean-link">Buka statistik →</button></div><div class="mini-stats" id="miniStats"></div><div class="clean-category-list" id="homeCategories"><span>Memuat kategori…</span></div></article><article class="clean-panel monitoring-panel"><div class="clean-panel-head"><div><span>PANTAU PERUBAHAN</span><h2>Ikuti pembaruan</h2><p>Lihat status dan waktu pembaruan masalah publik.</p></div><button data-view="monitoring" class="clean-link">Buka pantauan →</button></div><div class="monitoring-flow"><div>📌<strong>Masalah tercatat</strong><span>Wilayah & kategori</span></div><div>🔄<strong>Data diperbarui</strong><span>Status & waktu</span></div><div>💬<strong>Warga menanggapi</strong><span>Laporan terkait</span></div></div></article></section><section class="clean-info"><div><span>WASKITA</span><h2>Lihat. Pahami. Antisipasi.</h2><p>Satu pintu untuk menjelajahi wilayah, masalah publik, data, laporan warga, dan perubahan.</p></div><div class="info-actions"><button data-view="problems" class="clean-primary">Lihat Masalah</button><button data-view="data" class="clean-ghost-dark">Lihat Data</button></div></section></div>`;wire();loadHomeData();document.getElementById('cleanSearch')?.addEventListener('submit',e=>{e.preventDefault();const q=document.getElementById('cleanQuestion')?.value.trim();if(q)window.render?.('result',q)})}function wire(){document.querySelectorAll('#home [data-view]').forEach(b=>b.onclick=()=>window.render?.(b.dataset.view));try{window.lucide?.createIcons()}catch{}}async function loadHomeData(){try{const[problems,regions]=await Promise.all([api('/rest/v1/problems?select=id,title,category,status,updated_at,region_id&order=updated_at.desc&limit=100'),api('/rest/v1/regions?select=id,level,parent_region_id&source_name=eq.BIG&limit=1000')]);const levels={province:0,regency:0,district:0};regions.forEach(r=>{const s=String(r.level||'').toLowerCase();if(s.includes('prov'))levels.province++;else if(s.includes('kab')||s.includes('kota')||s.includes('regenc'))levels.regency++;else if(s.includes('kec')||s.includes('district'))levels.district++});[levels.province,levels.regency,levels.district,problems.length].forEach((v,i)=>{const e=document.querySelectorAll('#liveStats article b')[i];if(e)e.textContent=v.toLocaleString('id-ID')});const issues=document.getElementById('homeIssues');issues.innerHTML=problems.slice(0,6).map(x=>`<button class="clean-issue" data-problem="${esc(x.id)}"><i>${icon(x.category)}</i><div><b>${esc(x.title||'Masalah tanpa judul')}</b><span>${esc(x.category||'Masalah')} · ${esc(x.status||'tercatat')} · ${x.updated_at?new Date(x.updated_at).toLocaleDateString('id-ID'):''}</span></div><em>Detail →</em></button>`).join('')||'<div class="clean-empty">Belum ada masalah publik yang tersedia.</div>';issues.querySelectorAll('[data-problem]').forEach(b=>b.onclick=()=>window.render?.('problem-detail',b.dataset.problem));const known=['Infrastruktur','Ekonomi','Sosial','Kesehatan','Pendidikan','Lingkungan','Kemiskinan','Transportasi','Pertanian','Bencana','Air Bersih'];const counts={};problems.forEach(x=>counts[x.category||'Lainnya']=(counts[x.category||'Lainnya']||0)+1);const cats=document.getElementById('homeCategories');cats.innerHTML=known.map(k=>`<button data-view="problems"><span>${icon(k)} ${k}</span><b>${counts[k]||0} masalah</b></button>`).join('')+(Object.keys(counts).filter(k=>!known.includes(k)).slice(0,5).map(k=>`<button data-view="problems"><span>${icon(k)} ${esc(k)}</span><b>${counts[k]} masalah</b></button>`).join(''));cats.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>window.render?.('problems'));document.getElementById('miniStats').innerHTML=`<div><b>${problems.length}</b><span>Total masalah</span></div><div><b>${Object.keys(counts).length}</b><span>Kategori</span></div><div><b>${new Set(problems.map(x=>x.region_id).filter(Boolean)).size}</b><span>Wilayah terisi</span></div>`}catch{document.getElementById('homeIssues')?.replaceChildren(Object.assign(document.createElement('div'),{className:'clean-empty',textContent:'Data masalah belum dapat dimuat.'}))}}const previousRender=window.render;window.render=async function(v,x=''){if(v==='home'){home();window.scrollTo({top:0,behavior:'smooth'});return}if(typeof previousRender==='function')return previousRender(v,x)};document.addEventListener('DOMContentLoaded',home)})();